def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append(cells)

    # Remove the patch whose marked cells form the most dispersed pattern.
    def rank(cells):
        marks = [(y, x) for y, x in cells if grid[y][x] == 9]
        if len(marks) < 2:
            return (-1, -1)
        spread = sum(abs(y1-y2) + abs(x1-x2)
                     for i, (y1, x1) in enumerate(marks)
                     for y2, x2 in marks[i+1:])
        return spread, len(marks)

    target = max(objects, key=rank)
    for y, x in target:
        out[y][x] = 0
    return out
